CREATE TABLE IF NOT EXISTS shop_promo_material(id BIGINT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(80) NOT NULL,category VARCHAR(40) NOT NULL,image VARCHAR(800) NOT NULL,copy_text VARCHAR(2000) NOT NULL,channel CHAR(1) NOT NULL DEFAULT 'C',target VARCHAR(20) NOT NULL DEFAULT 'product',product_id BIGINT NULL,enabled BOOLEAN NOT NULL DEFAULT FALSE,sort_order INT NOT NULL DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
